qb_string* qb_fullpath(qb_string* path) {
    if (!path) return qb_string_empty();
    const char* path_str = qb_string_data(path);
    char* resolved = realpath(path_str, NULL);
    if (resolved) {
        qb_string* result = qb_string_new(resolved);
        free(resolved);
        return result;
    }
    return qb_string_retain(path);
}

